import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    command = "wmic cpu get loadpercentage" if platform.system() == "Windows" else "top -b -n 1 | grep \"Cpu(s)\""
    logs = []
    start_time = time.time()

    while time.time() - start_time < duration:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        try:
            cpu_data = subprocess.check_output(command, shell=True).decode()
            if platform.system() == "Windows":
                usage = int(cpu_data.splitlines()[1].strip())
            else:
                usage = float([x for x in cpu_data.split() if "%" in x][0].replace("%", ""))
            logs.append({"timestamp": timestamp, "cpu_usage": usage})
        except Exception:
            pass
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as logfile:
            json.dump(logs, logfile)
    except IOError:
        return None

    return LOGFILE_PATH

