    command = None
    if platform.system() == "Windows":
        command = ["typeperf", r"\Processor(_Total)\% Processor Time", "-sc", "1"]
    elif platform.system() in ["Linux", "Darwin"]:
        command = ["mpstat", "1", "1"]
    else:
        raise ValueError("Unsupported operating system")
    records = []
    start_time = time.time()
    while time.time() - start_time < duration:
        try:
            output = subprocess.check_output(command, stderr=subprocess.DEVNULL)
            if platform.system() == "Windows":
                usage = float(output.decode().strip().split("\n")[2].split(",")[1].replace('"', ''))
            else:
                usage = 100.0 - float(output.decode().strip().split("\n")[-1].split()[-1])
            records.append({"timestamp": time.time(), "cpu_usage": usage})
            time.sleep(interval)
        except Exception:
            continue
    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(records, logfile)
    except IOError:
        return None
    return LOGFILE_PATH

